<?php

namespace App\Support;

class BuckcrestAssets
{
    /**
     * High-resolution Chocolate Gold crest monogram as base64 Data URI.
     * Guaranteed zero-network, zero-404 immediate inline rendering.
     */
    public static function crestDataUri(): string
    {
        return 'data:image/png;base64,';
    }

    /**
     * Binary PNG stream of the crest.
     */
    public static function crestPngBinary(): string
    {
        return base64_decode('');
    }
}
